from google.cloud import recommender_v1

client = recommender_v1.RecommenderClient()

# List active VM rightsizing recommendations for a project
parent = (
    "projects/my-project/locations/us-central1"
    "/recommenders/google.compute.instance.MachineTypeRecommender"
)
recommendations = client.list_recommendations(
    request={"parent": parent, "filter": "stateInfo.state=ACTIVE"}
)
for rec in recommendations:
    print(rec.description, rec.primary_impact.cost_projection.cost)
